INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c989-7207-9d14-d6b789fbf7e3'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'A painting was worth 25% more in 2024 than in 2023. In 2025, its value was 20% less than its 2024 value. If its 2025 value was $18,000, find its 2023 value.', '$18,000', '2024 value = 18,000 ÷ 0.8 = 22,500. 2023 value = 22,500 ÷ 1.25 = $18,000.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.265Z'::timestamptz, '2026-08-15T07:50:40.265Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c99c-7f8c-9607-b6bb3b0374f4'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'A traveller can exchange $800 at a rate of $1 = RM3.40 in Singapore. In Malaysia, the rate is RM100 = $33.00. Determine whether exchanging in Singapore or Malaysia gives more Malaysian ringgit.', 'Singapore (RM2720 vs RM2424.24)', 'Singapore gives 800 × 3.40 = RM2720. Malaysia gives $800 ÷ 0.33 ≈ RM2424.24. Exchanging in Singapore yields RM295.76 more.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.284Z'::timestamptz, '2026-08-15T07:50:40.284Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c9a6-7c0e-9762-307ce591f974'::uuid, '019f9df7-a2a2-791f-bec6-372d238905de'::uuid, 'The vectors PQ = (8, 3) and QR = (-2, 7). Find the length of PR.', '2√34 (approx 11.7)', 'PR = PQ + QR = (8 - 2, 3 + 7) = (6, 10). Length |PR| = √(6² + 10²) = √136 = 2√34.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.294Z'::timestamptz, '2026-08-15T07:50:40.294Z'::timestamptz) ON CONFLICT (id) DO NOTHING;